function renderQuizEditor(course, lesson, quiz) {
  const questions = quiz?.questions || [{}];
  const editing = Boolean(quiz);
  return `<form class="studio-form quiz-create-form" data-quiz-form data-quiz-course="${course.id}" data-quiz-lesson="${lesson.id}" data-existing-quiz="${editing}" ${editing ? "hidden" : ""}>
    <label><span>${escapeHtml(t("quizTitleLabel"))}</span><input name="title" minlength="3" maxlength="200" value="${escapeHtml(quiz?.title || "")}" required /></label>
    <label><span>${escapeHtml(t("passingScore"))}</span><input name="passing_score" type="number" min="0" max="100" value="${quiz?.passing_score ?? 60}" required /></label>
    <div class="quiz-question-editor-list">${questions.map((question) => `<fieldset class="studio-question" data-question>
      <label><span>${escapeHtml(t("questionLabel"))}</span><input name="prompt" minlength="3" value="${escapeHtml(question.prompt || "")}" required /></label>
      <label><span>${escapeHtml(t("choicesLabel"))}</span><textarea name="choices" rows="3" placeholder="Example choice A&#10;Example choice B" required>${(question.choices || []).map(escapeHtml).join("\n")}</textarea></label>
      <div class="studio-form-row"><label><span>${escapeHtml(t("correctIndexLabel"))}</span><input name="correct_index" type="number" min="0" value="${question.correct_index ?? 0}" required /></label><label><span>${escapeHtml(t("pointsLabel"))}</span><input name="points" type="number" min="1" max="100" value="${question.points ?? 1}" required /></label></div>
      <button class="button button-outline" type="button" data-remove-question>${escapeHtml(t("removeQuestionButton"))}</button>
    </fieldset>`).join("")}</div>
    <div class="studio-form-actions"><button class="button button-outline" type="button" data-add-question>${escapeHtml(t("addQuestionButton"))}</button><button class="button button-dark" type="submit">${escapeHtml(t(editing ? "saveEditsButton" : "createQuizButton"))}</button>${editing ? `<button class="button button-outline" type="button" data-cancel-edit>${escapeHtml(t("cancelEditButton"))}</button>` : ""}</div>
    <p class="studio-form-message" role="status"></p>
  </form>`;
}

async function loadInstructorCourses() {
  const container = $("#ownedCourses");
  container.innerHTML = `<div class="panel-empty">${escapeHtml(t("instructorTitle"))}…</div>`;
  try {
    const courses = await api("/courses");
    if (!courses.length) { container.innerHTML = `<p class="panel-empty">${escapeHtml(t("emptyOwnedCourses"))}</p>`; return; }
    const cards = await Promise.all(courses.map(async (course) => {
      const [lessons, analytics] = await Promise.all([
        api(`/courses/${course.id}/lessons`),
        api(`/courses/${course.id}/analytics`)
      ]);
      const lessonData = await Promise.all(lessons.map(async (lesson) => ({
        lesson,
        quiz: await api(`/courses/${course.id}/lessons/${lesson.id}/quiz/manage`).catch(() => null)
      })));
      return { course, lessonData, analytics };
    }));
    container.innerHTML = cards.map(({course,lessonData,analytics}) => `<article class="owned-course-card">
      <div class="owned-course-head"><div><span class="studio-status ${course.is_published ? "is-published" : "is-draft"}">${escapeHtml(t(course.is_published ? "publishedLabel" : "draftLabel"))}</span><h3>${escapeHtml(course.title)}</h3><p>${escapeHtml(course.description || "")}</p></div><div class="owned-course-actions"><button class="button button-outline" data-edit-course="${course.id}">${escapeHtml(t("editCourseButton"))}</button><button class="button button-outline" data-delete-course="${course.id}">${escapeHtml(t("deleteCourseButton"))}</button><button class="button button-outline" data-publish-course="${course.id}" data-published="${course.is_published}">${escapeHtml(t(course.is_published ? "unpublishButton" : "publishButton"))}</button></div></div>
      <form class="studio-form course-edit-form" data-course-edit="${course.id}" hidden><label><span>${escapeHtml(t("courseTitleLabel"))}</span><input name="title" minlength="3" maxlength="200" value="${escapeHtml(course.title)}" required /></label><label><span>${escapeHtml(t("courseDescriptionLabel"))}</span><textarea name="description" rows="2">${escapeHtml(course.description || "")}</textarea></label><div class="studio-form-row"><label><span>${escapeHtml(t("courseLanguageLabel"))}</span><select name="language">${[["uz","O‘zbekcha"],["en","English"],["ru","Русский"],["ko","한국어"]].map(([code,label])=>`<option value="${code}" ${course.language===code?"selected":""}>${label}</option>`).join("")}</select></label><label><span>${escapeHtml(t("courseLevelLabel"))}</span><select name="level">${[["beginner","levelBeginner"],["intermediate","levelIntermediate"],["advanced","levelAdvanced"]].map(([code,key])=>`<option value="${code}" ${course.level===code?"selected":""}>${escapeHtml(t(key))}</option>`).join("")}</select></label></div><div class="studio-form-actions"><button class="button button-dark" type="submit">${escapeHtml(t("saveEditsButton"))}</button><button class="button button-outline" type="button" data-cancel-edit>${escapeHtml(t("cancelEditButton"))}</button></div><p class="studio-form-message" role="status"></p></form>
      <div class="course-analytics"><div><b>${analytics.enrollment_count}</b><small>${escapeHtml(t("analyticsEnrolled"))}</small></div><div><b>${analytics.completed_learners}/${analytics.enrollment_count}</b><small>${escapeHtml(t("analyticsCompleted"))} · ${analytics.completion_rate}%</small></div><div><b>${analytics.average_rating !== null ? `${analytics.average_rating} ★` : "—"}</b><small>${escapeHtml(t("analyticsRating"))} · ${analytics.review_count}</small></div><div><b>${analytics.final_exam_attempts ? `${analytics.final_exam_pass_rate}%` : "—"}</b><small>${escapeHtml(t("analyticsExamPass"))} · ${analytics.final_exam_passes}/${analytics.final_exam_attempts}</small></div></div>
      <form class="studio-form lesson-create-form" data-lesson-course="${course.id}"><div class="section-label">${escapeHtml(t("lessonTitleLabel"))}</div><label><span>${escapeHtml(t("lessonTitleLabel"))}</span><input name="title" minlength="3" maxlength="200" required /></label><label><span>${escapeHtml(t("lessonContentLabel"))}</span><textarea name="content" rows="3" required></textarea></label><label><span>${escapeHtml(t("lessonPositionLabel"))}</span><input name="position" type="number" min="1" value="${lessonData.length+1}" required /></label><button class="button button-dark" type="submit">${escapeHtml(t("addLessonButton"))}</button><p class="studio-form-message" role="status"></p></form>
      <div class="owned-lessons"><div class="section-label">${escapeHtml(t("quizForLesson"))}</div><p class="quiz-per-lesson-note">${escapeHtml(t("quizPerLessonNote"))}</p>${lessonData.length ? lessonData.map(({lesson,quiz}) => `<div class="owned-lesson"><div class="owned-lesson-head"><div><b>${escapeHtml(lesson.position)}. ${escapeHtml(lesson.title)}</b><small>${quiz ? `${escapeHtml(t("quizReady"))} · ${quiz.questions.length}` : escapeHtml(t("noQuiz"))}</small></div><div class="owned-course-actions">${quiz ? `<button type="button" class="button button-outline" data-edit-quiz="${lesson.id}">${escapeHtml(t("editQuizButton"))}</button><button type="button" class="button button-outline" data-delete-quiz="${quiz.id}" data-course-id="${course.id}" data-lesson-id="${lesson.id}">${escapeHtml(t("deleteQuizButton"))}</button>` : ""}<button type="button" class="button button-outline" data-edit-lesson="${lesson.id}">${escapeHtml(t("editLessonButton"))}</button><button type="button" class="button button-outline" data-delete-lesson="${lesson.id}" data-course-id="${course.id}">${escapeHtml(t("deleteLessonButton"))}</button></div></div><form class="studio-form lesson-edit-form" data-lesson-edit="${course.id}" data-lesson-id="${lesson.id}" hidden><label><span>${escapeHtml(t("lessonTitleLabel"))}</span><input name="title" minlength="3" maxlength="200" value="${escapeHtml(lesson.title)}" required /></label><label><span>${escapeHtml(t("lessonContentLabel"))}</span><textarea name="content" rows="3" required>${escapeHtml(lesson.content)}</textarea></label><label><span>${escapeHtml(t("lessonPositionLabel"))}</span><input name="position" type="number" min="1" value="${lesson.position}" required /></label><div class="studio-form-actions"><button class="button button-dark" type="submit">${escapeHtml(t("saveEditsButton"))}</button><button class="button button-outline" type="button" data-cancel-edit>${escapeHtml(t("cancelEditButton"))}</button></div><p class="studio-form-message" role="status"></p></form>${renderQuizEditor(course,lesson,quiz)}</div>`).join("") : `<p class="panel-empty">${escapeHtml(t("emptyLessons"))}</p>`}</div>
    </article>`).join("");
    container.querySelectorAll("[data-edit-course]").forEach((button) => button.addEventListener("click", () => {
      const form=container.querySelector(`[data-course-edit="${button.dataset.editCourse}"]`);
      form.hidden=!form.hidden;
    }));
    container.querySelectorAll("[data-edit-lesson]").forEach((button) => button.addEventListener("click", () => {
      const form=button.closest(".owned-lesson").querySelector("[data-lesson-edit]");
      form.hidden=!form.hidden;
    }));
    container.querySelectorAll("[data-delete-course]").forEach((button) => button.addEventListener("click", async () => {
      if (!window.confirm(t("confirmDeleteCourse"))) return;
      button.disabled = true;
      try {
        await api(`/courses/${button.dataset.deleteCourse}`, {method:"DELETE"});
        await loadInstructorCourses();
        await loadCourses();
      } catch(error) {
        button.disabled = false;
        alert(error.message || t("studioError"));
      }
    }));
    container.querySelectorAll("[data-edit-quiz]").forEach((button) => button.addEventListener("click", () => {
      const form=button.closest(".owned-lesson").querySelector("[data-quiz-form]");
      form.hidden=!form.hidden;
    }));
    container.querySelectorAll("[data-delete-quiz]").forEach((button) => button.addEventListener("click", async () => {
      if (!window.confirm(t("confirmDeleteQuiz"))) return;
      button.disabled = true;
      try {
        await api(`/courses/${button.dataset.courseId}/lessons/${button.dataset.lessonId}/quiz`, {method:"DELETE"});
        await loadInstructorCourses();
      } catch(error) {
        button.disabled = false;
        alert(error.message || t("studioError"));
      }
    }));
    container.querySelectorAll("[data-delete-lesson]").forEach((button) => button.addEventListener("click", async () => {
      if (!window.confirm(t("confirmDeleteLesson"))) return;
      button.disabled = true;
      try {
        await api(`/courses/${button.dataset.courseId}/lessons/${button.dataset.deleteLesson}`, {method:"DELETE"});
        await loadInstructorCourses();
        await loadCourses();
      } catch(error) {
        button.disabled = false;
        alert(error.message || t("studioError"));
      }
    }));
    container.querySelectorAll("[data-cancel-edit]").forEach((button) => button.addEventListener("click", () => { button.closest("form").hidden=true; }));
    container.querySelectorAll("[data-course-edit]").forEach((form) => form.addEventListener("submit", async (event) => {
      event.preventDefault();
      const message=form.querySelector(".studio-form-message");
      const values=Object.fromEntries(new FormData(form));
      try { await api(`/courses/${form.dataset.courseEdit}`,{method:"PUT",body:JSON.stringify(values)}); await loadInstructorCourses(); await loadCourses(); }
      catch(error) { message.textContent=error.message || t("studioError"); }
    }));
    container.querySelectorAll("[data-lesson-edit]").forEach((form) => form.addEventListener("submit", async (event) => {
      event.preventDefault();
      const message=form.querySelector(".studio-form-message");
      const values=Object.fromEntries(new FormData(form));
      try { await api(`/courses/${form.dataset.lessonEdit}/lessons/${form.dataset.lessonId}`,{method:"PUT",body:JSON.stringify({...values,position:Number(values.position)})}); await loadInstructorCourses(); await loadCourses(); }
      catch(error) { message.textContent=error.message || t("studioError"); }
    }));
    container.querySelectorAll("[data-publish-course]").forEach((button) => button.addEventListener("click", async () => {
      button.disabled = true;
      try {
        const action = button.dataset.published === "true" ? "unpublish" : "publish";
        await api(`/courses/${button.dataset.publishCourse}/${action}`, {method:"POST"});
        await loadInstructorCourses();
        await loadCourses();
      } catch(error) { button.disabled = false; alert(error.message || t("studioError")); }
    }));
    container.querySelectorAll("[data-lesson-course]").forEach((form) => form.addEventListener("submit", async (event) => {
      event.preventDefault();
      const message=form.querySelector(".studio-form-message");
      try { const values=Object.fromEntries(new FormData(form)); await api(`/courses/${form.dataset.lessonCourse}/lessons`,{method:"POST",body:JSON.stringify({...values,position:Number(values.position)})}); await loadInstructorCourses(); }
      catch(error) { message.textContent=error.message || t("studioError"); }
    }));
    container.querySelectorAll("[data-remove-question]").forEach((button) => button.addEventListener("click", () => {
      const list=button.closest(".quiz-question-editor-list");
      if (list.querySelectorAll("[data-question]").length > 1) button.closest("[data-question]").remove();
    }));
    container.querySelectorAll("[data-add-question]").forEach((button) => button.addEventListener("click", () => {
      const list=button.closest("form").querySelector(".quiz-question-editor-list");
      const first=list.querySelector("[data-question]");
      const question=first.cloneNode(true);
      question.querySelectorAll("input,textarea").forEach((field) => { field.value=field.name==="correct_index"?"0":field.name==="points"?"1":""; });
      list.append(question);
    }));
    container.querySelectorAll("[data-quiz-form]").forEach((form) => form.addEventListener("submit", async (event) => {
      event.preventDefault();
      const message=form.querySelector(".studio-form-message");
      try {
        const values=Object.fromEntries(new FormData(form));
        const questions=[...form.querySelectorAll("[data-question]")].map((block) => {
          const choices=block.querySelector('[name="choices"]').value.split("\n").map((choice)=>choice.trim()).filter(Boolean);
          return {prompt:block.querySelector('[name="prompt"]').value,choices,correct_index:Number(block.querySelector('[name="correct_index"]').value),points:Number(block.querySelector('[name="points"]').value)};
        });
        await api(`/courses/${form.dataset.quizCourse}/lessons/${form.dataset.quizLesson}/quiz`,{method:form.dataset.existingQuiz==="true"?"PUT":"POST",body:JSON.stringify({title:values.title,passing_score:Number(values.passing_score),questions})});
        await loadInstructorCourses();
      } catch(error) { message.textContent=error.message || t("studioError"); }
    }));
  } catch(error) { container.innerHTML=`<p class="form-error">${escapeHtml(error.message || t("studioError"))}</p>`; }
}

function decodeBase64Url(value) {
  const base64=value.replace(/-/g,"+").replace(/_/g,"/");
  const binary=atob(base64+"=".repeat((4-base64.length%4)%4));
  return Uint8Array.from(binary,(char)=>char.charCodeAt(0));
}
function encodeBase64Url(value) {
  return btoa(String.fromCharCode(...new Uint8Array(value))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");
}
function publicKeyOptions(json) {
  const options=JSON.parse(json);
  options.challenge=decodeBase64Url(options.challenge);
  if (options.user?.id) options.user.id=decodeBase64Url(options.user.id);
  if (options.excludeCredentials) options.excludeCredentials=options.excludeCredentials.map(item=>({...item,id:decodeBase64Url(item.id)}));
  if (options.allowCredentials) options.allowCredentials=options.allowCredentials.map(item=>({...item,id:decodeBase64Url(item.id)}));
  return options;
}
function serializeCredential(credential) {
  return {id:credential.id,rawId:encodeBase64Url(credential.rawId),type:credential.type,authenticatorAttachment:credential.authenticatorAttachment,response:{clientDataJSON:encodeBase64Url(credential.response.clientDataJSON),...(credential.response.attestationObject?{attestationObject:encodeBase64Url(credential.response.attestationObject)}:{}),...(credential.response.authenticatorData?{authenticatorData:encodeBase64Url(credential.response.authenticatorData)}:{}),...(credential.response.signature?{signature:encodeBase64Url(credential.response.signature)}:{}),...(credential.response.userHandle?{userHandle:encodeBase64Url(credential.response.userHandle)}:{}),...(credential.response.getTransports?{transports:credential.response.getTransports()}: {})},clientExtensionResults:credential.getClientExtensionResults()};
}
async function getPasskeyStatus() { return api("/auth/passkeys/me"); }
async function registerPasskey() {
  if (!window.PublicKeyCredential || !navigator.credentials) throw new Error(t("passkeyUnsupported"));
  const start=await api("/auth/passkeys/registration/options",{method:"POST",body:"{}"});
  const credential=await navigator.credentials.create({publicKey:publicKeyOptions(start.publicKey)});
  if (!credential) throw new Error(t("passkeyRegistrationFailed"));
  await api("/auth/passkeys/registration/verify",{method:"POST",body:JSON.stringify({challenge_id:start.challenge_id,credential:serializeCredential(credential),label:navigator.userAgent.includes("iPhone")||navigator.userAgent.includes("Mac")?"This Apple device":"This device"})});
  await refreshPasskeyStatus();
}
async function refreshPasskeyStatus() {
  const status=await getPasskeyStatus();
  const text=$("#passkeyStatus");
  if (text) text.textContent=status.enabled?t("passkeyEnabled"):t("passkeyMissing");
  return status;
}
async function ensurePasskey() {
  let status=await getPasskeyStatus();
  if (!status.enabled) { await registerPasskey(); status=await getPasskeyStatus(); }
  if (!status.enabled) throw new Error(t("passkeyRegistrationFailed"));
}
async function authenticateWithPasskey(purpose) {
  await ensurePasskey();
  const start=await api("/auth/passkeys/authentication/options",{method:"POST",body:JSON.stringify({purpose})});
  const credential=await navigator.credentials.get({publicKey:publicKeyOptions(start.publicKey)});
  if (!credential) throw new Error(t("passkeyVerifyFailed"));
  const result=await api("/auth/passkeys/authentication/verify",{method:"POST",body:JSON.stringify({challenge_id:start.challenge_id,credential:serializeCredential(credential)})});
  return result.proof;
}

let profileAvatarObjectUrl = null;
let profileAvatarRequestId = 0;
async function renderProfile(profile) {
  user = profile;
  const form = $("#profileForm");
  form.elements.full_name.value = profile.full_name || "";
  form.elements.age.value = profile.age ?? "";
  form.elements.bio.value = profile.bio || "";
  const avatar = $("#profileAvatar");
  const initials = $("#profileInitials");
  const requestId=++profileAvatarRequestId;
  avatar.hidden = true;
  initials.hidden = false;
  initials.textContent = (profile.full_name || "?").trim().split(/\s+/).slice(0,2).map((part)=>part[0]).join("").toUpperCase();
  if (profile.avatar_url) {
    try {
      const response=await fetch(profile.avatar_url,{headers:{Authorization:`Bearer ${accessToken}`}});
      if (!response.ok) throw new Error("Profile photo unavailable");
      const objectUrl=URL.createObjectURL(await response.blob());
      if (requestId !== profileAvatarRequestId) { URL.revokeObjectURL(objectUrl); return; }
      if (profileAvatarObjectUrl) URL.revokeObjectURL(profileAvatarObjectUrl);
      profileAvatarObjectUrl=objectUrl;
      avatar.src=objectUrl;
      avatar.alt=profile.full_name || t("profilePhotoLabel");
      avatar.hidden=false;
      initials.hidden=true;
    } catch { /* Keep the initials fallback if the private photo cannot be loaded. */ }
  }
}

async function loadDashboard() {
  if (!accessToken) { updateAuthUI(); return; }
  updateAuthUI();
  await loadCourses();
  const coursesArea = $("#enrolledCourses");
  coursesArea.innerHTML = `<div class="course-placeholder">${escapeHtml(t("dashboardTitle"))}…</div>`;
  try {
    const [enrollments, recommendationData, plans, profile] = await Promise.all([
      api("/enrollments/me"), api("/recommendations/me?limit=4"), api("/learning-plans/me"), api("/auth/me")
    ]);
    await renderProfile(profile);
    await refreshPasskeyStatus();
    renderRecommendations(recommendationData.recommendations || []);
    renderPlans(plans || []);
    await renderEnrolledCourses(enrollments || []);
    await loadInstructorCourses();
  } catch (error) {
    coursesArea.innerHTML = `<div class="course-placeholder">${escapeHtml(error.message || t("genericError"))}</div>`;
  }
}
async function renderEnrolledCourses(enrollments) {
  const container = $("#enrolledCourses");
  const entries = await Promise.all(enrollments.map(async (enrollment) => {
    const [lessons, progress, certificate, review] = await Promise.all([
      api(`/courses/${enrollment.course_id}/lessons`),
      api(`/courses/${enrollment.course_id}/progress/me`),
      api(`/courses/${enrollment.course_id}/certificate/me`).catch(() => null),
      api(`/courses/${enrollment.course_id}/reviews/me`).catch(() => null)
    ]);
    const exam = progress.total_lessons > 0 && progress.completed_lessons === progress.total_lessons
      ? await api(`/courses/${enrollment.course_id}/final-exam`).catch(() => null)
      : null;
    return { enrollment, lessons, progress, certificate, exam, review };
  }));
  if (!entries.length) container.innerHTML = `<div class="course-placeholder">${t("emptyEnrollments")}</div>`;
  else container.innerHTML = entries.map(({ enrollment, lessons, progress, certificate, exam, review }) => {
    const items = lessons.map((lesson) => {
      const done = progress.completed_lesson_ids.includes(lesson.id);
      return `<div class="lesson-item"><span class="lesson-status ${done ? "done" : ""}">${done ? "✓" : "○"}</span><div class="lesson-entry"><span class="lesson-name">${escapeHtml(lesson.title)}</span><div class="lesson-content" id="lesson-${lesson.id}">${escapeHtml(lesson.content)}</div></div>${done ? `<span class="completed-label">${t("completed")}</span>` : `<button class="button button-outline" data-complete="${lesson.id}" data-course="${enrollment.course_id}">${t("markComplete")}</button>`}<button class="button button-outline quiz-open" data-quiz-course="${enrollment.course_id}" data-quiz-lesson="${lesson.id}">${t("openQuiz")}</button><button class="lesson-toggle" data-toggle="lesson-${lesson.id}" aria-label="${t("openLesson")}">⌄</button><div class="quiz-area" id="quiz-${lesson.id}" hidden></div></div>`;
    }).join("");
    return `<article class="enrolled-card" id="course-${enrollment.course_id}"><div class="enrolled-top"><div><div class="section-label">${t("progress")}</div><h3>${escapeHtml(enrollment.course_title)}</h3><p>${lessons.length} ${t("lessonCount")}</p></div><strong>${progress.progress_percent}%</strong></div><div class="progress-track course-progress" style="--progress:${progress.progress_percent}%"><span></span></div><div class="progress-summary"><span>${progress.completed_lessons}/${progress.total_lessons} ${t("completed")}</span><span>${progress.progress_percent}%</span></div><div class="lessons-list">${items || `<div class="panel-empty">${t("emptyLessons")}</div>`}</div><form class="plan-form" data-plan-course="${enrollment.course_id}"><label>${t("studyDays")}<select name="weekly_study_days"><option value="2">2</option><option value="3" selected>3</option><option value="5">5</option><option value="7">7</option></select></label><label>${t("sessionMinutes")}<select name="session_minutes"><option value="20">20</option><option value="30" selected>30</option><option value="45">45</option><option value="60">60</option></select></label><button class="button button-dark" type="submit">${t("planButton")}</button></form><p class="form-error" data-plan-error="${enrollment.course_id}" hidden></p>${progress.total_lessons > 0 && progress.completed_lessons === progress.total_lessons ? exam ? exam.passed ? `<button class="button button-dark certificate-button" data-certificate="${enrollment.course_id}" data-issued="${certificate ? "true" : "false"}">${certificate ? t("viewCertificate") : t("certificateButton")}</button>` : `<button class="button button-dark final-exam-button" data-final-exam="${enrollment.course_id}">${t("finalExam")}${exam.latest_score !== null ? ` · ${exam.latest_score}%` : ""}</button>` : `<p class="exam-unavailable">${t("finalExamUnavailable")}</p>` : ""}${progress.total_lessons > 0 && progress.completed_lessons === progress.total_lessons ? `<form class="course-review-form" data-review-course="${enrollment.course_id}"><h4>${escapeHtml(t("reviewTitle"))}</h4><label><span>${escapeHtml(t("reviewRating"))}</span><select name="rating">${[5,4,3,2,1].map((rating)=>`<option value="${rating}" ${Number(review?.rating || 5)===rating?"selected":""}>${rating} ★</option>`).join("")}</select></label><label><span>${escapeHtml(t("reviewComment"))}</span><textarea name="comment" rows="2" maxlength="2000" placeholder="${escapeHtml(t("reviewPlaceholder"))}">${escapeHtml(review?.comment || "")}</textarea></label><button class="button button-outline" type="submit">${escapeHtml(t("submitReview"))}</button><p class="review-form-message" role="status"></p></form>` : ""}</article>`;
  }).join("");
  const completeEntries = entries.filter(({ progress }) => progress.total_lessons > 0 && progress.completed_lessons === progress.total_lessons);
  const completedLessons = entries.reduce((sum, { progress }) => sum + progress.completed_lessons, 0);
  const certificates = entries.filter(({ certificate }) => certificate);
  const summaryItems = [
    [entries.length, t("courseCountLabel")],
    [completeEntries.length, t("completedCoursesCountLabel")],
    [completedLessons, t("completedLessonsCountLabel")],
    [certificates.length, t("certificatesCountLabel")]
  ];
  $("#learningOverview").innerHTML = summaryItems.map(([count,label]) => `<article class="learning-stat"><b>${count}</b><span>${escapeHtml(label)}</span></article>`).join("");
  $("#completedCourseList").innerHTML = completeEntries.length
    ? completeEntries.map(({ enrollment, progress, certificate, exam }) => `<article class="learner-list-card"><div><b>${escapeHtml(enrollment.course_title)}</b><span>${progress.completed_lessons}/${progress.total_lessons} ${escapeHtml(t("completed"))}</span></div><span class="learner-list-status">${escapeHtml(certificate ? t("viewCertificate") : exam?.passed ? t("certificateButton") : t("finalExam"))}</span><a class="button button-outline button-small" href="#course-${enrollment.course_id}">${escapeHtml(t("myCoursesAndLessons"))}</a></article>`).join("")
    : `<p class="panel-empty">${escapeHtml(t("emptyCompletedCourses"))}</p>`;
  $("#myCertificateList").innerHTML = certificates.length
    ? certificates.map(({ certificate }) => {
        const issuedDate = new Intl.DateTimeFormat(language,{year:"numeric",month:"short",day:"numeric"}).format(new Date(certificate.issued_at));
        return `<article class="learner-list-card certificate-list-card"><div><b>${escapeHtml(certificate.course_title)}</b><span>${escapeHtml(t("certificateCode"))}: ${escapeHtml(certificate.certificate_code)}</span><span>${escapeHtml(t("issuedOn"))}: ${escapeHtml(issuedDate)}</span></div><a class="button button-outline button-small" href="/app/verify.html?code=${encodeURIComponent(certificate.certificate_code)}">${escapeHtml(t("navVerifyCertificate"))}</a></article>`;
      }).join("")
    : `<p class="panel-empty">${escapeHtml(t("emptyCertificates"))}</p>`;
  container.querySelectorAll("[data-complete]").forEach((button) => button.addEventListener("click", async () => {
    button.disabled = true;
    try { await api(`/courses/${button.dataset.course}/progress/lessons/${button.dataset.complete}/complete`, { method:"POST" }); await loadDashboard(); }
    catch (error) { button.disabled = false; alert(error.message); }
  }));
  container.querySelectorAll("[data-final-exam]").forEach((button) => button.addEventListener("click", () => openFinalExam(button.dataset.finalExam)));
  container.querySelectorAll("[data-certificate]").forEach((button) => button.addEventListener("click", async () => {
    button.disabled = true;
    try {
      let certificate;
      if (button.dataset.issued === "true") certificate=await api(`/courses/${button.dataset.certificate}/certificate/me`);
      else {
        const proof=await authenticateWithPasskey("certificate");
        certificate=await api(`/courses/${button.dataset.certificate}/certificate`, { method:"POST", headers:{"X-Passkey-Proof":proof} });
      }
      showCertificate(certificate);
      button.dataset.issued = "true";
      button.textContent = t("viewCertificate");
    } catch (error) { alert(error.message || t("certificateError")); }
    finally { button.disabled = false; }
  }));
  container.querySelectorAll("[data-review-course]").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const message=form.querySelector(".review-form-message");
    const values=Object.fromEntries(new FormData(form));
    try {
      await api(`/courses/${form.dataset.reviewCourse}/reviews/me`,{method:"PUT",body:JSON.stringify({rating:Number(values.rating),comment:values.comment || null})});
      message.textContent=t("reviewSaved");
    } catch(error) { message.textContent=error.message || t("studioError"); }
  }));
  container.querySelectorAll("[data-quiz-course]").forEach((button) => button.addEventListener("click", () => openQuiz(button.dataset.quizCourse, button.dataset.quizLesson)));
  container.querySelectorAll("[data-toggle]").forEach((button) => button.addEventListener("click", () => {
    const panel = document.getElementById(button.dataset.toggle);
    panel.classList.toggle("open");
    button.textContent = panel.classList.contains("open") ? "⌃" : "⌄";
    button.setAttribute("aria-label", panel.classList.contains("open") ? t("hideLesson") : t("openLesson"));
  }));
  container.querySelectorAll("[data-plan-course]").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const errorBox = container.querySelector(`[data-plan-error="${form.dataset.planCourse}"]`);
    errorBox.hidden = true;
    const values = Object.fromEntries(new FormData(form));
    try {
      await api("/learning-plans/generate", { method:"POST", body:JSON.stringify({ course_id:form.dataset.planCourse, weekly_study_days:Number(values.weekly_study_days), session_minutes:Number(values.session_minutes) }) });
      await loadDashboard();
      $("#planList").scrollIntoView({ behavior:"smooth", block:"center" });
    } catch { errorBox.textContent = t("planError"); errorBox.hidden = false; }
  }));
}
async function openQuiz(courseId, lessonId) {
  const panel = document.getElementById(`quiz-${lessonId}`);
  panel.hidden = false;
  panel.innerHTML = `<p class="panel-empty">${t("quizLoading")}</p>`;
  try {
    const quiz = await api(`/courses/${courseId}/lessons/${lessonId}/quiz`);
    const questions = quiz.questions.map((question) => `<fieldset class="quiz-question"><legend>${question.position}. ${escapeHtml(question.prompt)}</legend><div class="quiz-choices">${question.choices.map((choice, index) => `<label><input type="radio" name="${question.id}" value="${index}" required><span>${escapeHtml(choice)}</span></label>`).join("")}</div></fieldset>`).join("");
    panel.innerHTML = `<div class="quiz-heading"><div><h4>${escapeHtml(quiz.title || t("quizTitle"))}</h4><p>${t("passingScore")}: ${quiz.passing_score}%</p></div></div><p class="quiz-hint">${t("selectAnswers")}</p><form class="quiz-form" data-quiz-id="${quiz.id}">${questions}<button class="button button-dark" type="submit">${t("submitQuiz")}</button><p class="quiz-result" role="status"></p></form><div class="attempt-history" id="attempts-${lessonId}"></div>`;
    renderQuizHistory(lessonId, await api(`/courses/${courseId}/lessons/${lessonId}/quiz/attempts/me`));
    panel.querySelector("[data-quiz-id]").addEventListener("submit", async (event) => {
      event.preventDefault();
      const quizForm = event.currentTarget;
      if (!quizForm.reportValidity()) return;
      const answers = quiz.questions.map((question) => ({ question_id:question.id, selected_index:Number(new FormData(quizForm).get(question.id)) }));
      const submit = quizForm.querySelector("button[type=submit]");
      submit.disabled = true;
      try {
        const attempt = await api(`/courses/${courseId}/lessons/${lessonId}/quiz/attempts`, { method:"POST", body:JSON.stringify({ answers }) });
        const result = quizForm.querySelector(".quiz-result");
        result.className = `quiz-result ${attempt.passed ? "passed" : "not-passed"}`;
        result.textContent = `${t("result")}: ${attempt.score_percent}% · ${attempt.correct_count}/${attempt.total_questions} ${t("correctAnswers")} — ${t(attempt.passed ? "passed" : "notPassed")}`;
        renderQuizHistory(lessonId, await api(`/courses/${courseId}/lessons/${lessonId}/quiz/attempts/me`));
      } catch (error) {
        quizForm.querySelector(".quiz-result").textContent = error.message || t("quizError");
      } finally { submit.disabled = false; }
    });
  } catch (error) {
    panel.innerHTML = `<p class="panel-empty">${error.status === 404 ? t("noQuiz") : t("quizError")}</p>`;
  }
}
function renderQuizHistory(lessonId, attempts) {
  const container = document.getElementById(`attempts-${lessonId}`);
  if (!container) return;
  container.innerHTML = `<h5>${t("previousAttempts")}</h5>${attempts.length ? attempts.slice(0, 5).map((attempt, index) => `<p>${index + 1}. ${attempt.score_percent}% · ${attempt.correct_count}/${attempt.total_questions} ${t("correctAnswers")} · ${t(attempt.passed ? "passed" : "notPassed")}</p>`).join("") : `<p>${t("noAttempts")}</p>`}`;
}

function renderRecommendations(recommendations) {
  const container = $("#recommendationList");
  if (!recommendations.length) { container.innerHTML = `<div class="panel-empty">${t("emptyRecommendations")}</div>`; return; }
  container.innerHTML = recommendations.map((item) => `<article class="recommendation-card"><h4>${escapeHtml(item.title)}</h4><p>${escapeHtml(item.description || "")}</p><p class="reasons">${escapeHtml((item.reasons || []).join(" · "))}</p><button class="button button-outline" data-recommend="${item.course_id}">${t("enroll")}</button></article>`).join("");
  container.querySelectorAll("[data-recommend]").forEach((button) => button.addEventListener("click", async () => {
    button.disabled = true;
    try { await api(`/courses/${button.dataset.recommend}/enroll`, { method:"POST" }); await loadDashboard(); }
    catch (error) { button.disabled = false; alert(error.message); }
  }));
}
function renderPlans(plans) {
  const container = $("#planList");
  if (!plans.length) { container.innerHTML = `<div class="panel-empty">${t("emptyPlans")}</div>`; return; }
  container.innerHTML = plans.slice(0, 4).map((plan) => `<article class="plan-card"><h4>${escapeHtml(plan.course_title)}</h4><p>${plan.estimated_weeks} ${t("planWeeks")} · ${plan.plan_items.length} ${t("planSessions")} · ${plan.session_minutes} ${t("minutesSuffix")}</p><ol class="plan-items">${plan.plan_items.slice(0, 5).map((item) => `<li>${escapeHtml(item.lesson_title)} · ${item.week_number} ${t("planWeeks")} · ${item.session_minutes} ${t("minutesSuffix")}</li>`).join("")}</ol></article>`).join("");
}
