$("#profilePhotoInput").addEventListener("change", async (event) => {
  const input=event.currentTarget;
  const file=input.files?.[0];
  if (!file) return;
  const message=$("#profileMessage");
  try {
    if (file.size > 10 * 1024 * 1024) throw new Error(t("profilePhotoError"));
    const bitmap=await createImageBitmap(file);
    const side=Math.min(bitmap.width,bitmap.height);
    const canvas=document.createElement("canvas"); canvas.width=512; canvas.height=512;
    canvas.getContext("2d").drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,512,512);
    bitmap.close();
    const blob=await new Promise((resolve)=>canvas.toBlob(resolve,"image/webp",0.86));
    if (!blob) throw new Error(t("profilePhotoError"));
    const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error(t("profilePhotoError")));reader.readAsDataURL(blob);});
    const updated=await api("/auth/me/avatar",{method:"PUT",body:JSON.stringify({data_url:dataUrl})});
    await renderProfile(updated);
    message.textContent=t("profilePhotoSaved");
  } catch(error) { message.textContent=error.message || t("profilePhotoError"); }
  finally { input.value=""; }
});
$("#courseCreateForm").addEventListener("submit", async (event) => {
  event.preventDefault();
  const form=event.currentTarget;
  const message=$("#courseCreateMessage");
  message.textContent="";
  const values=Object.fromEntries(new FormData(form));
  try {
    await api("/courses",{method:"POST",body:JSON.stringify(values)});
    form.reset();
    await loadInstructorCourses();
    await loadCourses();
  } catch(error) { message.textContent=error.message || t("studioError"); }
});
form.addEventListener("submit", async (event) => {
  event.preventDefault();
  const values = Object.fromEntries(new FormData(form));
  const message = $("#formMessage");
  const submit = $("#authSubmit");
  submit.disabled = true;
  try {
    const newAccount=authMode === "register";
    if (newAccount) {
      await api("/auth/register", { method:"POST", body:JSON.stringify({ ...values, preferred_language:language }) });
    }
    const result = await api("/auth/login", { method:"POST", body:JSON.stringify({ email:values.email, password:values.password }) });
    accessToken = result.access_token;
    localStorage.setItem("studyflow-token", accessToken);
    user = await api("/auth/me");
    if (newAccount) await registerPasskey();
    language = user.preferred_language || language;
    setLanguage(language, false);
    message.className = "form-message success";
    message.textContent = t(authMode === "register" ? "registerSuccess" : "loginSuccess");
    await loadDashboard();
    setTimeout(() => dialog.close(), 900);
  } catch (error) { message.className = "form-message"; message.textContent = error.message || t("genericError"); }
  finally { submit.disabled = false; }
});

setLanguage(language);
